type DataReader struct {
	reader *bufio.Reader
	tokens []string
	index  int
}

func NewDataReader(reader *bufio.Reader) *DataReader {
	return &DataReader{reader: reader}
}

func (dr *DataReader) next() string {
	for dr.index >= len(dr.tokens) {
		line, err := dr.reader.ReadString('\n')
		if err != nil {
			return ""
		}
		dr.tokens = strings.Fields(line)
		dr.index = 0
	}
	token := dr.tokens[dr.index]
	dr.index++
	return token
}

func (dr *DataReader) nextInt() int {
	return int(dr.nextToken())
}

func (dr *DataReader) nextToken() int {
	return int(dr.next()[0] - '0')
}

func (dr *DataReader) nextLine() string {
	line, _ := dr.reader.ReadString('\n')
	return line
}

func solve(out *bufio.Writer, n, k int, s string) {
	used := make([]bool, n)

	var dfs func(u int) bool
	dfs = func(u int) bool {
		if u < 0 || u >= n || used[u] || s[u] == '#' {
			return false
		}
		if s[u] == 'T' {
			return true
		}
		used[u] = true

		return dfs(u-k) || dfs(u+k)
	}

	result := dfs(strings.Index(s, "G"))
	if result {
		fmt.Fprintln(out, "YES")
	} else {
		fmt.Fprintln(out, "NO")
	}
}

func main() {
	var reader *os.File
	var writer *os.File
	if os.Getenv("ONLINE_JUDGE") == "" {
		reader, _ = os.Open("input.txt")
		writer, _ = os.Create("output.txt")
	} else {
		reader = os.Stdin
		writer = os.Stdout
	}

	dr := NewDataReader(bufio.NewReader(reader))
	out := bufio.NewWriter(writer)
	defer out.Flush()

	n := dr.nextInt()
	k := dr.nextInt()
	s := dr.next()

	solve(out, n, k, s)
}
